#include <stdio.h>

int main() {
    int N, M;
    scanf("%d %d", &N, &M);
    char grid[505][505];
    for (int i = 0; i < N; i++) {
        scanf("%s", grid[i]);
    }

    int queue[250005];
    int front = 0, rear = 0;

    // Encontra o ponto inicial de vazamento na primeira linha
    for (int j = 0; j < M; j++) {
        if (grid[0][j] == 'o') {
            queue[rear++] = j; // i = 0
            break;
        }
    }

    while (front < rear) {
        int idx = queue[front++];
        int i = idx / M;
        int j = idx % M;

        // Propagação vertical para baixo
        if (i + 1 < N && grid[i + 1][j] == '.') {
            grid[i + 1][j] = 'o';
            queue[rear++] = (i + 1) * M + j;
        }

        // Propagação horizontal se houver prateleira logo abaixo
        if (i + 1 < N && grid[i + 1][j] == '#') {
            // Esquerda
            if (j - 1 >= 0 && grid[i][j - 1] == '.') {
                grid[i][j - 1] = 'o';
                queue[rear++] = i * M + (j - 1);
            }
            // Direita
            if (j + 1 < M && grid[i][j + 1] == '.') {
                grid[i][j + 1] = 'o';
                queue[rear++] = i * M + (j + 1);
            }
        }
    }

    // Impressão da matriz final
    for (int i = 0; i < N; i++) {
        printf("%s\n", grid[i]);
    }

    return 0;
}
